INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-6-07', 'ngsl-6', 'Thông dụng 2.501–2.809 · Bộ 7', 'New General Service List, thứ hạng 2.501–2.809', '#3da9fc', 'BookOpen', 7);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 1, 'reflection', 'hình ảnh phản chiếu; sự suy ngẫm', 'noun', '[{"en":"She could see her reflection in the shop window.","vi":"Cô ấy có thể thấy hình ảnh phản chiếu của mình trên cửa kính cửa hàng."},{"en":"The reflection of the mountains in the lake was beautiful.","vi":"Hình ảnh phản chiếu của những ngọn núi trên mặt hồ thật đẹp."},{"en":"After careful reflection, I decided to accept the job offer.","vi":"Sau khi suy ngẫm kỹ, tôi quyết định nhận lời mời làm việc."}]', '[{"phrase":"careful reflection"},{"phrase":"on reflection"},{"phrase":"a moment of reflection"}]', NULL, '/rɪˈflekʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refle/reflection__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 2, 'nerve', 'dây thần kinh; sự can đảm', 'noun', '[{"en":"The accident caused nerve damage in his left hand.","vi":"Vụ tai nạn đã gây tổn thương dây thần kinh ở tay trái của anh ấy."},{"en":"I finally found the nerve to ask for a raise.","vi":"Cuối cùng tôi cũng đủ can đảm để xin tăng lương."},{"en":"She lost her nerve at the last minute and didn''t jump.","vi":"Cô ấy mất hết can đảm vào phút cuối và không nhảy."}]', '[{"phrase":"nerve damage"},{"phrase":"lose your nerve"},{"phrase":"have the nerve to"}]', 'get on someone''s nerves = làm ai phát bực', '/nɜːrv/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/n/ner/nerve/nerve__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 3, 'determination', 'sự quyết tâm', 'noun', '[{"en":"Her determination to finish the marathon impressed everyone.","vi":"Quyết tâm hoàn thành cuộc chạy marathon của cô ấy khiến mọi người ấn tượng."},{"en":"With hard work and determination, you can learn any language.","vi":"Với sự chăm chỉ và quyết tâm, bạn có thể học bất kỳ ngôn ngữ nào."},{"en":"He showed great determination while recovering from his injury.","vi":"Anh ấy đã thể hiện quyết tâm lớn trong lúc hồi phục sau chấn thương."}]', '[{"phrase":"great determination"},{"phrase":"show determination"},{"phrase":"determination to succeed"}]', 'không đếm được', '/dɪˌtɜːrmɪˈneɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/det/deter/determination__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 4, 'altogether', 'hoàn toàn; tổng cộng', 'adverb', '[{"en":"The meal cost us sixty dollars altogether, including the tip.","vi":"Bữa ăn tốn của chúng tôi tổng cộng sáu mươi đô la, tính cả tiền boa."},{"en":"There were twenty people at the party altogether.","vi":"Có tổng cộng hai mươi người tại bữa tiệc."},{"en":"My grandfather used to smoke, but he''s stopped altogether.","vi":"Ông tôi từng hút thuốc, nhưng giờ ông đã bỏ hẳn."}]', '[{"phrase":"stop altogether"},{"phrase":"disappear altogether"},{"phrase":"not altogether"}]', 'altogether (hoàn toàn) ≠ all together (tất cả cùng nhau)', '/ˌɔːltəˈɡeðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alt/altog/altogether__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 5, 'fiction', 'truyện hư cấu, tiểu thuyết; điều bịa đặt', 'noun', '[{"en":"I prefer reading fiction to reading history books.","vi":"Tôi thích đọc truyện hư cấu hơn đọc sách lịch sử."},{"en":"She has written several works of science fiction.","vi":"Cô ấy đã viết một vài tác phẩm khoa học viễn tưởng."},{"en":"His story about meeting a famous singer was pure fiction.","vi":"Câu chuyện anh ta kể về việc gặp một ca sĩ nổi tiếng hoàn toàn là bịa đặt."}]', '[{"phrase":"science fiction"},{"phrase":"a work of fiction"},{"phrase":"pure fiction"}]', 'không đếm được', '/ˈfɪkʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fic/ficti/fiction__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 6, 'carpet', 'tấm thảm', 'noun', '[{"en":"Could you vacuum the carpet before our guests arrive tonight?","vi":"Bạn có thể hút bụi tấm thảm trước khi khách đến tối nay không?"},{"en":"We bought a new carpet for the living room.","vi":"Chúng tôi đã mua một tấm thảm mới cho phòng khách."},{"en":"The cat is sleeping on the carpet near the fireplace.","vi":"Con mèo đang ngủ trên tấm thảm gần lò sưởi."}]', '[{"phrase":"vacuum the carpet"},{"phrase":"thick carpet"},{"phrase":"red carpet"}]', NULL, '/ˈkɑːrpɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/car/carpe/carpet__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 7, 'cluster', 'cụm, chùm; nhóm', 'noun', '[{"en":"A small cluster of houses stood at the foot of the hill.","vi":"Một cụm nhà nhỏ nằm dưới chân đồi."},{"en":"Students gathered in small clusters around the notice board.","vi":"Học sinh tụ tập thành từng nhóm nhỏ quanh bảng thông báo."},{"en":"In our garden, the grapes grow in large clusters every summer.","vi":"Trong vườn nhà chúng tôi, nho mọc thành từng chùm lớn mỗi mùa hè."}]', '[{"phrase":"a cluster of"},{"phrase":"small cluster"},{"phrase":"in clusters"}]', NULL, '/ˈklʌstər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/clu/clust/cluster__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 8, 'confusion', 'sự nhầm lẫn; sự bối rối', 'noun', '[{"en":"There was some confusion about the time of the meeting.","vi":"Đã có chút nhầm lẫn về giờ họp."},{"en":"To avoid confusion, please write your name on your bag.","vi":"Để tránh nhầm lẫn, hãy viết tên bạn lên túi."},{"en":"She looked at me in confusion when I spoke French.","vi":"Cô ấy nhìn tôi đầy bối rối khi tôi nói tiếng Pháp."}]', '[{"phrase":"avoid confusion"},{"phrase":"cause confusion"},{"phrase":"confusion about"}]', NULL, '/kənˈfjuːʒn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xconf/xconfusion__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 9, 'hurry', 'vội vàng, khẩn trương', 'verb', '[{"en":"We need to hurry or we''ll miss the bus.","vi":"Chúng ta phải nhanh lên, không thì sẽ lỡ xe buýt."},{"en":"Hurry up, the movie starts in ten minutes!","vi":"Nhanh lên, phim bắt đầu trong mười phút nữa!"},{"en":"She hurried home when it started to rain.","vi":"Cô ấy vội vã về nhà khi trời bắt đầu mưa."}]', '[{"phrase":"hurry up"},{"phrase":"hurry home"},{"phrase":"hurry back"}]', 'in a hurry = đang vội', '/ˈhɜːri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hur/hurry/hurry__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 10, 'logic', 'logic; lý lẽ hợp lý', 'noun', '[{"en":"I don''t understand the logic behind this decision.","vi":"Tôi không hiểu logic đằng sau quyết định này."},{"en":"There is no logic in paying more for the same product.","vi":"Chẳng có lý gì khi trả nhiều tiền hơn cho cùng một sản phẩm."},{"en":"His argument sounds good, but the logic is weak.","vi":"Lập luận của anh ấy nghe có vẻ hay, nhưng logic thì yếu."}]', '[{"phrase":"the logic behind"},{"phrase":"simple logic"},{"phrase":"follow the logic"}]', 'không đếm được', '/ˈlɑːdʒɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/log/logic/logic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 11, 'controversial', 'gây tranh cãi', 'adjective', '[{"en":"Whether to allow phones in class is a controversial issue.","vi":"Có nên cho phép dùng điện thoại trong lớp hay không là một vấn đề gây tranh cãi."},{"en":"The movie''s ending was quite controversial among fans.","vi":"Cái kết của bộ phim khá gây tranh cãi trong giới người hâm mộ."},{"en":"The referee made a controversial decision in the final minute.","vi":"Trọng tài đã đưa ra một quyết định gây tranh cãi ở phút cuối."}]', '[{"phrase":"controversial issue"},{"phrase":"controversial decision"},{"phrase":"highly controversial"}]', NULL, '/ˌkɑːntrəˈvɜːrʃl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/x/xco/xcont/xcontroversial__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 12, 'raw', 'sống, chưa nấu chín; thô, chưa qua chế biến', 'adjective', '[{"en":"You shouldn''t eat raw chicken because it can make you sick.","vi":"Bạn không nên ăn thịt gà sống vì nó có thể làm bạn bị bệnh."},{"en":"I like to add raw carrots to my salad.","vi":"Tôi thích cho cà rốt sống vào món salad."},{"en":"The factory imports raw materials from several countries.","vi":"Nhà máy nhập khẩu nguyên liệu thô từ một vài quốc gia."}]', '[{"phrase":"raw materials"},{"phrase":"raw meat"},{"phrase":"raw fish"}]', NULL, '/rɔː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/raw/raw__/raw__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 13, 'grammar', 'ngữ pháp', 'noun', '[{"en":"My English grammar is good, but my pronunciation needs work.","vi":"Ngữ pháp tiếng Anh của tôi tốt, nhưng phát âm thì cần cải thiện."},{"en":"The teacher corrected the grammar mistakes in my essay.","vi":"Giáo viên đã sửa các lỗi ngữ pháp trong bài luận của tôi."},{"en":"Do you have a good grammar book for beginners?","vi":"Bạn có cuốn sách ngữ pháp nào tốt cho người mới bắt đầu không?"}]', '[{"phrase":"English grammar"},{"phrase":"grammar mistake"},{"phrase":"grammar book"},{"phrase":"grammar rules"}]', 'không đếm được', '/ˈɡræmər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/gramm/grammar__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 14, 'revise', 'sửa lại, điều chỉnh; ôn tập', 'verb', '[{"en":"I revised my essay three times before handing it in.","vi":"Tôi đã sửa lại bài luận ba lần trước khi nộp."},{"en":"The company has revised its prices for next year.","vi":"Công ty đã điều chỉnh giá cho năm tới."},{"en":"I need to revise for my history exam tomorrow.","vi":"Tôi cần ôn bài cho kỳ thi lịch sử ngày mai."}]', '[{"phrase":"revise for"},{"phrase":"revise a plan"},{"phrase":"revised version"}]', 'nghĩa "ôn tập" dùng ở Anh; Mỹ dùng review/study', '/rɪˈvaɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rev/revis/revise__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 15, 'hint', 'lời gợi ý; chút, dấu hiệu', 'noun', '[{"en":"If you can''t guess the answer, I''ll give you a hint.","vi":"Nếu bạn không đoán ra đáp án, tôi sẽ gợi ý cho bạn."},{"en":"He dropped a hint that he wanted a new bike for his birthday.","vi":"Cậu ấy bóng gió rằng mình muốn có một chiếc xe đạp mới vào dịp sinh nhật."},{"en":"There was a hint of sadness in her voice.","vi":"Trong giọng nói của cô ấy có chút buồn."}]', '[{"phrase":"give a hint"},{"phrase":"drop a hint"},{"phrase":"a hint of"}]', NULL, '/hɪnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hin/hint_/hint__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 16, 'hook', 'cái móc; lưỡi câu', 'noun', '[{"en":"Hang your coat on the hook behind the door.","vi":"Hãy treo áo khoác lên cái móc sau cánh cửa."},{"en":"My father put a small worm on the fishing hook.","vi":"Bố tôi móc một con giun nhỏ vào lưỡi câu."},{"en":"There are three hooks by the door for our keys.","vi":"Có ba cái móc cạnh cửa để treo chìa khóa của chúng tôi."}]', '[{"phrase":"coat hook"},{"phrase":"fishing hook"},{"phrase":"on a hook"}]', 'let someone off the hook = tha cho ai', '/hʊk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hoo/hook_/hook__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 17, 'bell', 'cái chuông; tiếng chuông', 'noun', '[{"en":"The school bell rings at seven thirty every morning.","vi":"Chuông trường reo lúc bảy giờ ba mươi mỗi sáng."},{"en":"Someone rang the bell, so I went to open the door.","vi":"Có người bấm chuông nên tôi ra mở cửa."},{"en":"Our cat wears a tiny bell around its neck.","vi":"Con mèo của chúng tôi đeo một cái chuông nhỏ quanh cổ."}]', '[{"phrase":"ring the bell"},{"phrase":"school bell"},{"phrase":"the bell rings"}]', NULL, '/bel/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/b/bel/bell_/bell__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 18, 'liquid', 'chất lỏng', 'noun', '[{"en":"The bottle was filled with a clear liquid that smelled like lemons.","vi":"Cái chai chứa đầy một chất lỏng trong suốt có mùi chanh."},{"en":"You can''t bring large bottles of liquid onto the plane.","vi":"Bạn không được mang những chai chất lỏng lớn lên máy bay."},{"en":"Drink plenty of liquids when you have a fever.","vi":"Khi bị sốt, bạn nên uống nhiều chất lỏng."}]', '[{"phrase":"clear liquid"},{"phrase":"plenty of liquids"}]', NULL, '/ˈlɪkwɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/liq/liqui/liquid__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 19, 'panic', 'hoảng sợ, hoảng loạn', 'verb', '[{"en":"Don''t panic, we still have plenty of time to catch the train.","vi":"Đừng hoảng, chúng ta vẫn còn nhiều thời gian để kịp chuyến tàu."},{"en":"She panicked when she couldn''t find her passport at the airport.","vi":"Cô ấy hoảng hốt khi không tìm thấy hộ chiếu ở sân bay."},{"en":"People started to panic when the lights suddenly went out.","vi":"Mọi người bắt đầu hoảng loạn khi đèn đột nhiên tắt."}]', '[{"phrase":"don''t panic"},{"phrase":"start to panic"},{"phrase":"in a panic"}]', 'panic – panicked – panicked', '/ˈpænɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pan/panic/panic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 20, 'uncle', 'chú, bác, cậu, dượng', 'noun', '[{"en":"My uncle lives on a farm in the countryside.","vi":"Chú tôi sống ở một trang trại dưới quê."},{"en":"We''re visiting my aunt and uncle this weekend.","vi":"Cuối tuần này chúng tôi sẽ đến thăm cô chú tôi."},{"en":"Her uncle taught her how to ride a bike.","vi":"Cậu của cô ấy đã dạy cô ấy đi xe đạp."}]', '[{"phrase":"aunt and uncle"},{"phrase":"favorite uncle"}]', NULL, '/ˈʌŋkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unc/uncle/uncle__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 21, 'rice', 'gạo; cơm; lúa', 'noun', '[{"en":"We eat rice with almost every meal at home.","vi":"Ở nhà, chúng tôi ăn cơm gần như mọi bữa."},{"en":"My grandparents grow rice in the fields near their village.","vi":"Ông bà tôi trồng lúa trên những cánh đồng gần làng."},{"en":"Could you buy a bag of rice on your way home?","vi":"Bạn mua giúp một bao gạo trên đường về nhà được không?"}]', '[{"phrase":"grow rice"},{"phrase":"a bowl of rice"},{"phrase":"fried rice"},{"phrase":"a bag of rice"}]', 'không đếm được', '/raɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ric/rice_/rice__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 22, 'slope', 'con dốc; sườn đồi', 'noun', '[{"en":"We walked slowly up the steep slope to the top.","vi":"Chúng tôi chậm rãi đi bộ lên con dốc đứng để lên tới đỉnh."},{"en":"Their house sits on a gentle slope overlooking the river.","vi":"Ngôi nhà của họ nằm trên một sườn đồi thoai thoải nhìn ra sông."},{"en":"Beginners should practice skiing on the easier slopes first.","vi":"Người mới bắt đầu nên tập trượt tuyết ở những con dốc dễ hơn trước."}]', '[{"phrase":"steep slope"},{"phrase":"gentle slope"},{"phrase":"ski slope"}]', NULL, '/sləʊp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/slo/slope/slope__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 23, 'happiness', 'hạnh phúc, niềm vui', 'noun', '[{"en":"Many people believe that money can''t buy happiness.","vi":"Nhiều người tin rằng tiền không mua được hạnh phúc."},{"en":"Her face was full of happiness when she saw her family.","vi":"Gương mặt cô ấy tràn đầy hạnh phúc khi thấy gia đình mình."},{"en":"We wish you both a lifetime of happiness together.","vi":"Chúng tôi chúc hai bạn trọn đời hạnh phúc bên nhau."}]', '[{"phrase":"buy happiness"},{"phrase":"true happiness"},{"phrase":"bring happiness"}]', 'không đếm được', '/ˈhæpinəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hap/happi/happiness__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 24, 'genuine', 'thật, chính hãng; chân thành', 'adjective', '[{"en":"Is this bag made of genuine leather?","vi":"Chiếc túi này làm bằng da thật phải không?"},{"en":"She showed genuine interest in my ideas.","vi":"Cô ấy thể hiện sự quan tâm thật lòng đến ý tưởng của tôi."},{"en":"He seems like a genuine person who really cares about others.","vi":"Anh ấy có vẻ là một người chân thành, thật sự quan tâm đến người khác."}]', '[{"phrase":"genuine leather"},{"phrase":"genuine interest"},{"phrase":"genuine concern"}]', NULL, '/ˈdʒenjuɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/genui/genuine__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 25, 'vessel', 'tàu, thuyền; mạch máu', 'noun', '[{"en":"The fishing vessel returned to port after a week at sea.","vi":"Tàu cá đã quay về cảng sau một tuần lênh đênh trên biển."},{"en":"A large cargo vessel was waiting outside the harbor.","vi":"Một tàu chở hàng lớn đang chờ bên ngoài bến cảng."},{"en":"Exercise helps keep your heart and blood vessels healthy.","vi":"Tập thể dục giúp tim và mạch máu của bạn khỏe mạnh."}]', '[{"phrase":"fishing vessel"},{"phrase":"cargo vessel"},{"phrase":"blood vessel"}]', NULL, '/ˈvesl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ves/vesse/vessel__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 26, 'verb', 'động từ', 'noun', '[{"en":"In this sentence, \"run\" is used as a verb.","vi":"Trong câu này, \"run\" được dùng như một động từ."},{"en":"Irregular verbs like \"go\" and \"take\" are hard to remember.","vi":"Các động từ bất quy tắc như \"go\" và \"take\" rất khó nhớ."},{"en":"Remember to put the verb in the past tense.","vi":"Nhớ chia động từ ở thì quá khứ nhé."}]', '[{"phrase":"irregular verb"},{"phrase":"main verb"},{"phrase":"phrasal verb"}]', NULL, '/vɜːrb/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/ver/verb_/verb__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 27, 'reckon', 'cho rằng, nghĩ; ước tính', 'verb', '[{"en":"I reckon it''s going to rain later this afternoon.","vi":"Tôi nghĩ chiều nay trời sẽ mưa."},{"en":"Do you reckon she''ll accept the job offer?","vi":"Bạn có nghĩ là cô ấy sẽ nhận lời mời làm việc không?"},{"en":"The trip is reckoned to take about three hours by car.","vi":"Chuyến đi được ước tính mất khoảng ba tiếng bằng ô tô."}]', '[{"phrase":"I reckon"},{"phrase":"I reckon so"}]', 'thân mật, hay dùng trong văn nói', '/ˈrekən/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rec/recko/reckon__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 28, 'silly', 'ngớ ngẩn, ngốc nghếch', 'adjective', '[{"en":"Sorry, I know it''s a silly question, but where''s the bathroom?","vi":"Xin lỗi, tôi biết đây là câu hỏi ngớ ngẩn, nhưng nhà vệ sinh ở đâu vậy?"},{"en":"Don''t be silly, you''re always welcome at our house.","vi":"Đừng ngốc thế, bạn lúc nào cũng được chào đón ở nhà chúng tôi."},{"en":"The kids were making silly faces at the camera.","vi":"Bọn trẻ đang làm mặt xấu trước ống kính."}]', '[{"phrase":"silly question"},{"phrase":"don''t be silly"},{"phrase":"silly mistake"},{"phrase":"feel silly"}]', NULL, '/ˈsɪli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sil/silly/silly__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-07', 29, 'transportation', 'giao thông vận tải; phương tiện đi lại', 'noun', '[{"en":"Public transportation in this city is cheap and reliable.","vi":"Giao thông công cộng ở thành phố này rẻ và đáng tin cậy."},{"en":"The price of the tour includes hotels and transportation.","vi":"Giá tour đã bao gồm khách sạn và phương tiện đi lại."},{"en":"Bicycles are the main form of transportation for many students here.","vi":"Xe đạp là phương tiện đi lại chính của nhiều sinh viên ở đây."}]', '[{"phrase":"public transportation"},{"phrase":"means of transportation"},{"phrase":"form of transportation"}]', 'Mỹ: transportation · Anh: transport; không đếm được', '/ˌtrænspərˈteɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tra/trans/transportation__us_3.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-6-08', 'ngsl-6', 'Thông dụng 2.501–2.809 · Bộ 8', 'New General Service List, thứ hạng 2.501–2.809', '#3da9fc', 'BookOpen', 8);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 1, 'harbor', 'cảng; bến cảng', 'noun', '[{"en":"The fishing boats returned to the harbor before the storm.","vi":"Những chiếc thuyền đánh cá đã quay về cảng trước cơn bão."},{"en":"We walked along the harbor and watched the ships come in.","vi":"Chúng tôi đi dạo dọc bến cảng và ngắm những con tàu cập bến."},{"en":"Our hotel room had a beautiful view of the harbor.","vi":"Phòng khách sạn của chúng tôi có tầm nhìn tuyệt đẹp ra bến cảng."}]', '[{"phrase":"in the harbor"},{"phrase":"natural harbor"},{"phrase":"harbor entrance"}]', 'Anh: harbour · Mỹ: harbor', '/ˈhɑrbər/', NULL, NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 2, 'comedy', 'hài kịch; phim hài', 'noun', '[{"en":"My brother loves watching comedy shows after a long day.","vi":"Anh trai tôi rất thích xem các chương trình hài sau một ngày dài."},{"en":"It''s a romantic comedy, so it has a happy ending.","vi":"Đó là một phim hài lãng mạn nên có kết thúc có hậu."},{"en":"She started her career doing stand-up comedy in small clubs.","vi":"Cô ấy bắt đầu sự nghiệp bằng việc diễn hài độc thoại ở các câu lạc bộ nhỏ."}]', '[{"phrase":"romantic comedy"},{"phrase":"stand-up comedy"},{"phrase":"comedy show"}]', NULL, '/ˈkɑːmədi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/comed/comedy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 3, 'chase', 'đuổi theo; theo đuổi', 'verb', '[{"en":"The children laughed as they chased after the ball.","vi":"Bọn trẻ cười đùa khi chạy đuổi theo quả bóng."},{"en":"Two police officers chased the thief down the street.","vi":"Hai cảnh sát đuổi theo tên trộm dọc con phố."},{"en":"Don''t spend your whole life chasing money and success.","vi":"Đừng dành cả đời để theo đuổi tiền bạc và thành công."}]', '[{"phrase":"chase after"},{"phrase":"chase a dream"},{"phrase":"chase away"}]', NULL, '/tʃeɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cha/chase/chase__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 4, 'storage', 'sự lưu trữ; chỗ chứa; bộ nhớ', 'noun', '[{"en":"We need more storage space for all these boxes.","vi":"Chúng ta cần thêm chỗ chứa đồ cho tất cả những cái hộp này."},{"en":"My phone is almost out of storage, so I deleted some photos.","vi":"Điện thoại của tôi gần hết bộ nhớ nên tôi đã xóa bớt vài bức ảnh."},{"en":"They put their old furniture in storage while they moved.","vi":"Họ gửi đồ nội thất cũ vào kho trong lúc chuyển nhà."}]', '[{"phrase":"storage space"},{"phrase":"in storage"},{"phrase":"data storage"}]', 'không đếm được', '/ˈstɔːrɪdʒ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sto/stora/storage__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 5, 'universe', 'vũ trụ; thế giới', 'noun', '[{"en":"Scientists believe the universe is about fourteen billion years old.","vi":"Các nhà khoa học tin rằng vũ trụ đã khoảng mười bốn tỷ năm tuổi."},{"en":"Do you think we are alone in the universe?","vi":"Bạn có nghĩ chúng ta đơn độc trong vũ trụ không?"},{"en":"The film takes place in a strange universe full of magic.","vi":"Bộ phim diễn ra trong một thế giới kỳ lạ đầy phép thuật."}]', '[{"phrase":"in the universe"},{"phrase":"the entire universe"}]', NULL, '/ˈjuːnɪvɜːrs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unive/universe__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 6, 'horrible', 'kinh khủng; tồi tệ', 'adjective', '[{"en":"The food at that restaurant was absolutely horrible.","vi":"Đồ ăn ở nhà hàng đó thật sự kinh khủng."},{"en":"I had a horrible dream last night and couldn''t fall asleep again.","vi":"Đêm qua tôi gặp một giấc mơ kinh khủng và không ngủ lại được."},{"en":"It was horrible of him to laugh at her mistake.","vi":"Anh ta thật tồi tệ khi cười nhạo lỗi sai của cô ấy."}]', '[{"phrase":"absolutely horrible"},{"phrase":"horrible feeling"},{"phrase":"horrible weather"}]', NULL, '/ˈhɔːrəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hor/horri/horrible__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 7, 'sheep', 'con cừu', 'noun', '[{"en":"The farmer keeps about two hundred sheep on his land.","vi":"Người nông dân nuôi khoảng hai trăm con cừu trên đất của mình."},{"en":"A few sheep were eating grass on the side of the hill.","vi":"Vài con cừu đang gặm cỏ trên sườn đồi."},{"en":"These sweaters are made from the wool of local sheep.","vi":"Những chiếc áo len này được làm từ lông của cừu địa phương."}]', '[{"phrase":"a flock of sheep"},{"phrase":"sheep farm"},{"phrase":"keep sheep"}]', 'số nhiều vẫn là sheep', '/ʃiːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/she/sheep/sheep__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 8, 'lover', 'người yêu; người mê thích', 'noun', '[{"en":"The two lovers walked hand in hand along the beach.","vi":"Đôi tình nhân nắm tay nhau đi dạo dọc bãi biển."},{"en":"As a coffee lover, I try every new café in town.","vi":"Là người mê cà phê, tôi thử mọi quán cà phê mới trong thành phố."},{"en":"This park is popular with dog lovers on weekends.","vi":"Công viên này được những người yêu chó ưa chuộng vào cuối tuần."}]', '[{"phrase":"music lover"},{"phrase":"dog lover"},{"phrase":"nature lover"}]', NULL, '/ˈlʌvər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lov/lover/lover__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 9, 'rat', 'chuột cống; con chuột', 'noun', '[{"en":"We saw a huge rat running near the trash cans.","vi":"Chúng tôi thấy một con chuột to chạy gần mấy thùng rác."},{"en":"Rats can carry diseases, so keep your kitchen clean.","vi":"Chuột có thể mang mầm bệnh, vì vậy hãy giữ bếp sạch sẽ."},{"en":"The old house was full of rats and spiders.","vi":"Ngôi nhà cũ đầy chuột và nhện."}]', '[{"phrase":"rat poison"},{"phrase":"lab rat"}]', 'rat (chuột to) ≠ mouse (chuột nhắt)', '/ræt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rat/rat__/rat__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 10, 'portrait', 'bức chân dung; sự miêu tả', 'noun', '[{"en":"A portrait of her grandmother hangs above the fireplace.","vi":"Một bức chân dung của bà cô ấy được treo phía trên lò sưởi."},{"en":"The artist spent three months painting the family portrait.","vi":"Họa sĩ đã mất ba tháng để vẽ bức chân dung gia đình."},{"en":"The book gives a clear portrait of life in a small village.","vi":"Cuốn sách đưa ra một bức tranh rõ nét về cuộc sống ở một ngôi làng nhỏ."}]', '[{"phrase":"paint a portrait"},{"phrase":"family portrait"},{"phrase":"portrait of"}]', NULL, '/ˈpɔːrtrət/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/por/portr/portrait__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 11, 'innocent', 'vô tội; ngây thơ', 'adjective', '[{"en":"Her lawyer was sure that she was completely innocent.","vi":"Luật sư của cô ấy chắc chắn rằng cô ấy hoàn toàn vô tội."},{"en":"He always believed his son was innocent of the crime.","vi":"Ông ấy luôn tin rằng con trai mình không phạm tội đó."},{"en":"The child looked up at me with big, innocent eyes.","vi":"Đứa trẻ ngước nhìn tôi bằng đôi mắt to tròn ngây thơ."}]', '[{"phrase":"innocent of"},{"phrase":"completely innocent"},{"phrase":"innocent eyes"}]', NULL, '/ˈɪnəsnt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/inn/innoc/innocent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 12, 'substitute', 'người thay thế; vật thay thế', 'noun', '[{"en":"You can use honey as a substitute for sugar.","vi":"Bạn có thể dùng mật ong để thay cho đường."},{"en":"Our teacher was sick, so a substitute taught the class.","vi":"Cô giáo chúng tôi bị ốm nên có một giáo viên khác dạy thay."},{"en":"The coach brought on a substitute in the second half.","vi":"Huấn luyện viên đã tung một cầu thủ dự bị vào sân trong hiệp hai."}]', '[{"phrase":"substitute for"},{"phrase":"substitute teacher"},{"phrase":"no substitute for"}]', 'cũng là động từ: substitute A for B (dùng A thay B)', '/ˈsʌbstɪtuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subst/substitute__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 13, 'supplement', 'thực phẩm bổ sung; phần bổ sung', 'noun', '[{"en":"My doctor told me to take a vitamin D supplement.","vi":"Bác sĩ bảo tôi uống thêm viên bổ sung vitamin D."},{"en":"Online lessons are a useful supplement to classes at school.","vi":"Các bài học trực tuyến là phần bổ sung hữu ích cho các lớp học ở trường."},{"en":"Many athletes take protein supplements after training.","vi":"Nhiều vận động viên dùng thực phẩm bổ sung protein sau khi tập luyện."}]', '[{"phrase":"dietary supplement"},{"phrase":"vitamin supplement"},{"phrase":"supplement to"}]', NULL, '/ˈsʌplɪmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sup/suppl/supplement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 14, 'adjustment', 'sự điều chỉnh; sự thích nghi', 'noun', '[{"en":"We made a few small adjustments to the plan.","vi":"Chúng tôi đã thực hiện vài điều chỉnh nhỏ cho kế hoạch."},{"en":"Moving to a new country requires a big adjustment.","vi":"Chuyển đến một đất nước mới đòi hỏi phải thích nghi rất nhiều."},{"en":"The mechanic made an adjustment to the brakes on my bike.","vi":"Thợ sửa xe đã điều chỉnh phanh xe đạp của tôi."}]', '[{"phrase":"make an adjustment"},{"phrase":"minor adjustment"},{"phrase":"adjustment to"}]', NULL, '/əˈdʒʌstmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/adj/adjus/adjustment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 15, 'reasonably', 'khá; hợp lý', 'adverb', '[{"en":"The hotel was clean and reasonably priced.","vi":"Khách sạn sạch sẽ và giá cả hợp lý."},{"en":"I speak French reasonably well, but my writing is poor.","vi":"Tôi nói tiếng Pháp khá tốt, nhưng viết thì kém."},{"en":"Please try to act reasonably, even when you feel angry.","vi":"Hãy cố gắng cư xử hợp lý, ngay cả khi bạn đang tức giận."}]', '[{"phrase":"reasonably priced"},{"phrase":"reasonably well"},{"phrase":"reasonably good"}]', NULL, '/ˈriːznəbli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/rea/reaso/reasonably__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 16, 'filter', 'bộ lọc; cái lọc', 'noun', '[{"en":"Remember to clean the air filter every few months.","vi":"Nhớ vệ sinh bộ lọc không khí vài tháng một lần."},{"en":"She added a filter to the photo before posting it.","vi":"Cô ấy thêm bộ lọc vào bức ảnh trước khi đăng."},{"en":"This water filter removes dirt and makes tap water safe.","vi":"Bộ lọc nước này loại bỏ cặn bẩn và giúp nước máy an toàn."}]', '[{"phrase":"water filter"},{"phrase":"air filter"},{"phrase":"coffee filter"}]', 'cũng là động từ: filter (lọc)', '/ˈfɪltər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fil/filte/filter__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 17, 'flexible', 'linh hoạt; dẻo dai', 'adjective', '[{"en":"My job has flexible hours, so I can pick up my kids.","vi":"Công việc của tôi có giờ giấc linh hoạt nên tôi có thể đón con."},{"en":"We''re flexible about the date, so just tell us what suits you.","vi":"Chúng tôi linh hoạt về ngày, nên bạn cứ cho biết ngày nào hợp với bạn."},{"en":"Yoga helps keep your body strong and flexible.","vi":"Yoga giúp cơ thể bạn khỏe mạnh và dẻo dai."}]', '[{"phrase":"flexible hours"},{"phrase":"flexible about"},{"phrase":"highly flexible"}]', NULL, '/ˈfleksəbl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fle/flexi/flexible__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 18, 'abstract', 'trừu tượng', 'adjective', '[{"en":"Love and freedom are abstract ideas that are hard to define.","vi":"Tình yêu và tự do là những khái niệm trừu tượng khó định nghĩa."},{"en":"I don''t really understand abstract art, but I like the colors.","vi":"Tôi không thực sự hiểu nghệ thuật trừu tượng, nhưng tôi thích màu sắc."},{"en":"His explanation was too abstract for the young students.","vi":"Lời giải thích của anh ấy quá trừu tượng đối với các học sinh nhỏ tuổi."}]', '[{"phrase":"abstract art"},{"phrase":"abstract idea"},{"phrase":"abstract concept"}]', NULL, '/ˈæbstrækt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/abs/abstr/abstract__us_2_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 19, 'tent', 'cái lều', 'noun', '[{"en":"Let''s put up the tent before it gets dark.","vi":"Chúng ta dựng lều trước khi trời tối đi."},{"en":"It rained all night, but we stayed dry inside the tent.","vi":"Trời mưa suốt đêm nhưng chúng tôi vẫn khô ráo trong lều."},{"en":"The wedding dinner was held in a large white tent.","vi":"Tiệc cưới được tổ chức trong một chiếc lều trắng lớn."}]', '[{"phrase":"put up a tent"},{"phrase":"pitch a tent"},{"phrase":"sleep in a tent"}]', NULL, '/tent/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tent_/tent__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 20, 'precise', 'chính xác; rõ ràng', 'adjective', '[{"en":"Can you tell me the precise time the train leaves?","vi":"Bạn có thể cho tôi biết chính xác giờ tàu chạy không?"},{"en":"The instructions for the machine were clear and very precise.","vi":"Hướng dẫn sử dụng máy rõ ràng và rất chính xác."},{"en":"To be precise, we have been waiting for forty minutes.","vi":"Nói cho chính xác thì chúng tôi đã chờ bốn mươi phút rồi."}]', '[{"phrase":"to be precise"},{"phrase":"precise time"},{"phrase":"precise details"}]', NULL, '/prɪˈsaɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/preci/precise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 21, 'distant', 'xa; xa cách', 'adjective', '[{"en":"In the distant future, people might live on other planets.","vi":"Trong tương lai xa, con người có thể sống trên các hành tinh khác."},{"en":"She dreams of traveling to distant countries one day.","vi":"Cô ấy mơ một ngày được đi du lịch đến những đất nước xa xôi."},{"en":"After the argument, she seemed cold and distant.","vi":"Sau cuộc cãi vã, cô ấy có vẻ lạnh lùng và xa cách."}]', '[{"phrase":"distant future"},{"phrase":"distant relative"},{"phrase":"distant memory"}]', NULL, '/ˈdɪstənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dis/dista/distant__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 22, 'stranger', 'người lạ', 'noun', '[{"en":"Parents tell their children not to talk to strangers.","vi":"Cha mẹ dặn con cái không được nói chuyện với người lạ."},{"en":"A kind stranger helped me carry my bags up the stairs.","vi":"Một người lạ tốt bụng đã giúp tôi xách túi lên cầu thang."},{"en":"When I first moved here, everyone was a complete stranger to me.","vi":"Khi tôi mới chuyển đến đây, ai cũng hoàn toàn xa lạ với tôi."}]', '[{"phrase":"complete stranger"},{"phrase":"total stranger"},{"phrase":"talk to strangers"}]', NULL, '/ˈstreɪndʒər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/stran/stranger__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 23, 'shade', 'bóng râm; sắc độ', 'noun', '[{"en":"Let''s sit in the shade of that big tree.","vi":"Chúng ta ngồi dưới bóng râm của cái cây to kia đi."},{"en":"It was so hot that the dog lay in the shade all day.","vi":"Trời nóng đến nỗi con chó nằm trong bóng râm cả ngày."},{"en":"I''d like this shirt in a lighter shade of blue.","vi":"Tôi muốn chiếc áo này với màu xanh nhạt hơn."}]', '[{"phrase":"in the shade"},{"phrase":"lighter shade"},{"phrase":"provide shade"}]', NULL, '/ʃeɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sha/shade/shade__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 24, 'grain', 'ngũ cốc; hạt', 'noun', '[{"en":"Farmers here grow grains such as wheat and rice.","vi":"Nông dân ở đây trồng các loại ngũ cốc như lúa mì và lúa gạo."},{"en":"There was a grain of sand stuck in my shoe.","vi":"Có một hạt cát bị kẹt trong giày tôi."},{"en":"Brown rice and other whole grains are good for your health.","vi":"Gạo lứt và các loại ngũ cốc nguyên hạt khác tốt cho sức khỏe."}]', '[{"phrase":"grain of sand"},{"phrase":"grain of rice"},{"phrase":"whole grain"}]', NULL, '/ɡreɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gra/grain/grain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 25, 'situate', 'đặt vào vị trí; nằm ở', 'verb', '[{"en":"The hotel is situated near the beach and the old town.","vi":"Khách sạn nằm gần bãi biển và khu phố cổ."},{"en":"Our school is situated on a quiet street near the park.","vi":"Trường chúng tôi nằm trên một con phố yên tĩnh gần công viên."},{"en":"The architect situated the kitchen on the sunny side of the house.","vi":"Kiến trúc sư đã đặt nhà bếp ở phía có nắng của ngôi nhà."}]', '[{"phrase":"situated in"},{"phrase":"situated near"},{"phrase":"conveniently situated"}]', 'thường dùng bị động: be situated in/on/near', '/ˈsɪtʃueɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sit/situa/situate__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 26, 'summarize', 'tóm tắt', 'verb', '[{"en":"Can you summarize the main points of the meeting?","vi":"Bạn có thể tóm tắt những ý chính của cuộc họp không?"},{"en":"In the last paragraph, summarize what you have learned.","vi":"Ở đoạn cuối, hãy tóm tắt những gì bạn đã học được."},{"en":"She summarized the long report in just a few sentences.","vi":"Cô ấy đã tóm tắt bản báo cáo dài chỉ trong vài câu."}]', '[{"phrase":"summarize the main points"},{"phrase":"briefly summarize"},{"phrase":"summarize the findings"}]', 'Anh: summarise · Mỹ: summarize', '/ˈsʌməraɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sum/summa/summarize__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 27, 'leap', 'nhảy; tăng vọt', 'verb', '[{"en":"The children leaped into the pool on the first hot day.","vi":"Bọn trẻ nhảy ùm xuống hồ bơi vào ngày nóng đầu tiên."},{"en":"He leaped out of bed when he heard the alarm.","vi":"Anh ấy bật dậy khỏi giường khi nghe tiếng chuông báo thức."},{"en":"Prices leaped by twenty percent in just one year.","vi":"Giá cả tăng vọt hai mươi phần trăm chỉ trong một năm."}]', '[{"phrase":"leap into"},{"phrase":"leap forward"},{"phrase":"leap at the chance"}]', 'leap – leaped/leapt – leaped/leapt', '/liːp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leap_/leap__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 28, 'snap', 'gãy tách; cáu gắt; chụp nhanh', 'verb', '[{"en":"The dry branch snapped when he stepped on it.","vi":"Cành cây khô gãy tách khi anh ấy giẫm lên."},{"en":"I''m sorry I snapped at you this morning.","vi":"Xin lỗi vì sáng nay tôi đã cáu gắt với bạn."},{"en":"She snapped a quick photo of the sunset from the train.","vi":"Cô ấy chụp vội một bức ảnh hoàng hôn từ trên tàu."}]', '[{"phrase":"snap at"},{"phrase":"snap in half"},{"phrase":"snap a photo"}]', NULL, '/snæp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sna/snap_/snap__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-08', 29, 'probability', 'xác suất; khả năng', 'noun', '[{"en":"The probability of rain tomorrow is about seventy percent.","vi":"Xác suất có mưa vào ngày mai là khoảng bảy mươi phần trăm."},{"en":"In all probability, the meeting will be canceled.","vi":"Rất có khả năng cuộc họp sẽ bị hủy."},{"en":"Today we learned how to calculate probability in math class.","vi":"Hôm nay chúng tôi học cách tính xác suất trong giờ toán."}]', '[{"phrase":"in all probability"},{"phrase":"high probability"},{"phrase":"probability of"}]', NULL, '/ˌprɑːbəˈbɪləti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pro/proba/probability__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-6-09', 'ngsl-6', 'Thông dụng 2.501–2.809 · Bộ 9', 'New General Service List, thứ hạng 2.501–2.809', '#3da9fc', 'BookOpen', 9);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 1, 'leather', 'da thuộc; đồ da', 'noun', '[{"en":"My father bought me a brown leather jacket for my birthday.","vi":"Bố tôi đã mua cho tôi một chiếc áo khoác da màu nâu nhân dịp sinh nhật."},{"en":"These shoes are made of real leather, so they last for years.","vi":"Đôi giày này làm bằng da thật nên dùng được nhiều năm."},{"en":"She keeps her passport in a small leather bag.","vi":"Cô ấy cất hộ chiếu trong một chiếc túi da nhỏ."}]', '[{"phrase":"leather jacket"},{"phrase":"real leather"},{"phrase":"leather bag"},{"phrase":"leather shoes"}]', 'không đếm được', '/ˈleðər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lea/leath/leather__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 2, 'uncertainty', 'sự không chắc chắn; sự bấp bênh', 'noun', '[{"en":"There is a lot of uncertainty about the future of the company.","vi":"Tương lai của công ty còn rất nhiều điều không chắc chắn."},{"en":"After losing his job, he lived with months of uncertainty.","vi":"Sau khi mất việc, anh ấy sống trong nhiều tháng bấp bênh."},{"en":"She could hear the uncertainty in her son''s voice.","vi":"Cô ấy nghe ra sự không chắc chắn trong giọng nói của con trai."}]', '[{"phrase":"uncertainty about"},{"phrase":"economic uncertainty"},{"phrase":"period of uncertainty"}]', NULL, '/ʌnˈsɜːrtnti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/unc/uncer/uncertainty__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 3, 'swear', 'thề; chửi thề', 'verb', '[{"en":"I swear I didn''t tell anyone your secret.","vi":"Tôi thề là tôi không kể bí mật của bạn cho ai cả."},{"en":"He swore that he would never lie to her again.","vi":"Anh ấy thề sẽ không bao giờ nói dối cô ấy nữa."},{"en":"Please don''t swear in front of the children.","vi":"Làm ơn đừng chửi thề trước mặt bọn trẻ."}]', '[{"phrase":"I swear"},{"phrase":"swear at someone"},{"phrase":"swear an oath"}]', 'swear – swore – sworn', '/swer/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/swe/swear/swear__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 4, 'refugee', 'người tị nạn', 'noun', '[{"en":"The refugees needed food, water and a safe place to sleep.","vi":"Những người tị nạn cần thức ăn, nước uống và một nơi an toàn để ngủ."},{"en":"Her grandparents came to this country as refugees many years ago.","vi":"Ông bà cô ấy đến đất nước này với tư cách người tị nạn từ nhiều năm trước."},{"en":"Volunteers at the refugee camp teach English to young children.","vi":"Các tình nguyện viên ở trại tị nạn dạy tiếng Anh cho trẻ nhỏ."}]', '[{"phrase":"refugee camp"},{"phrase":"refugee children"},{"phrase":"become a refugee"}]', NULL, '/ˌrefjuˈdʒiː/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/ref/refug/refugee__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 5, 'shore', 'bờ (biển, hồ, sông)', 'noun', '[{"en":"We walked along the shore and collected shells.","vi":"Chúng tôi đi dạo dọc bờ biển và nhặt vỏ sò."},{"en":"The boat slowly came back to shore before the storm.","vi":"Con thuyền từ từ quay vào bờ trước khi cơn bão đến."},{"en":"Their small cabin is on the shore of a quiet lake.","vi":"Căn nhà gỗ nhỏ của họ nằm bên bờ một hồ nước yên tĩnh."}]', '[{"phrase":"along the shore"},{"phrase":"on the shore"},{"phrase":"swim to shore"}]', NULL, '/ʃɔːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sho/shore/shore__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 6, 'monthly', 'hằng tháng', 'adjective', '[{"en":"Our monthly rent goes up by fifty dollars next year.","vi":"Tiền thuê nhà hằng tháng của chúng tôi sẽ tăng thêm năm mươi đô vào năm sau."},{"en":"The team has a monthly meeting on the first Friday.","vi":"Nhóm có một cuộc họp hằng tháng vào thứ Sáu đầu tiên của tháng."},{"en":"How much is your monthly phone bill?","vi":"Hóa đơn điện thoại hằng tháng của bạn là bao nhiêu?"}]', '[{"phrase":"monthly rent"},{"phrase":"monthly meeting"},{"phrase":"monthly payment"},{"phrase":"monthly salary"}]', NULL, '/ˈmʌnθli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mon/month/monthly__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 7, 'comprise', 'gồm có; cấu thành, chiếm', 'verb', '[{"en":"The apartment comprises two bedrooms, a kitchen and a small bathroom.","vi":"Căn hộ gồm hai phòng ngủ, một nhà bếp và một phòng tắm nhỏ."},{"en":"Children comprise about a third of the town''s population.","vi":"Trẻ em chiếm khoảng một phần ba dân số của thị trấn."},{"en":"The group mainly comprises students from nearby universities.","vi":"Nhóm này chủ yếu gồm sinh viên từ các trường đại học gần đó."}]', '[{"phrase":"mainly comprise"},{"phrase":"be comprised of"}]', 'comprise + danh từ (không cần "of")', '/kəmˈpraɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compr/comprise__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 8, 'stir', 'khuấy; cựa quậy', 'verb', '[{"en":"Stir the sauce constantly so it doesn''t burn.","vi":"Hãy khuấy nước sốt liên tục để nó không bị khét."},{"en":"She added some sugar and stirred her coffee.","vi":"Cô ấy cho thêm chút đường rồi khuấy cà phê."},{"en":"The baby stirred in his sleep but didn''t wake up.","vi":"Em bé cựa mình trong giấc ngủ nhưng không thức dậy."}]', '[{"phrase":"stir constantly"},{"phrase":"stir well"},{"phrase":"stir in"}]', 'stir – stirred – stirred', '/stɜːr/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sti/stir_/stir__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 9, 'excitement', 'sự phấn khích; sự háo hức', 'noun', '[{"en":"The children could hardly sleep because of their excitement about the trip.","vi":"Bọn trẻ gần như không ngủ được vì háo hức về chuyến đi."},{"en":"There was a lot of excitement in the stadium before the final.","vi":"Sân vận động tràn ngập sự phấn khích trước trận chung kết."},{"en":"She jumped up and down with excitement when she heard the news.","vi":"Cô ấy nhảy cẫng lên vì phấn khích khi nghe tin."}]', '[{"phrase":"with excitement"},{"phrase":"excitement about"},{"phrase":"great excitement"},{"phrase":"full of excitement"}]', NULL, '/ɪkˈsaɪtmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exc/excit/excitement__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 10, 'sigh', 'thở dài', 'verb', '[{"en":"He sighed and closed his laptop after a long day.","vi":"Anh ấy thở dài rồi gập máy tính lại sau một ngày dài."},{"en":"She sighed with relief when her son finally called.","vi":"Cô ấy thở phào nhẹ nhõm khi con trai cuối cùng cũng gọi điện."},{"en":"Why do you keep sighing when I ask about school?","vi":"Sao bạn cứ thở dài mỗi khi tôi hỏi về chuyện trường lớp?"}]', '[{"phrase":"sigh with relief"},{"phrase":"sigh deeply"},{"phrase":"sigh heavily"}]', NULL, '/saɪ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sig/sigh_/sigh__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 11, 'pregnancy', 'sự mang thai; thai kỳ', 'noun', '[{"en":"She felt tired during the first months of her pregnancy.","vi":"Cô ấy thấy mệt trong những tháng đầu mang thai."},{"en":"Doctors say women should avoid alcohol during pregnancy.","vi":"Bác sĩ cho biết phụ nữ nên tránh rượu bia trong thời gian mang thai."},{"en":"You can buy a pregnancy test at any pharmacy.","vi":"Bạn có thể mua que thử thai ở bất kỳ hiệu thuốc nào."}]', '[{"phrase":"during pregnancy"},{"phrase":"pregnancy test"},{"phrase":"early pregnancy"},{"phrase":"healthy pregnancy"}]', NULL, '/ˈpreɡnənsi/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pre/pregn/pregnancy__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 12, 'experimental', 'thử nghiệm; thể nghiệm', 'adjective', '[{"en":"The new drug is still at an experimental stage.","vi":"Loại thuốc mới vẫn đang ở giai đoạn thử nghiệm."},{"en":"Their band plays experimental music that mixes jazz and rock.","vi":"Ban nhạc của họ chơi nhạc thể nghiệm pha trộn giữa jazz và rock."},{"en":"The school is running an experimental program for young readers.","vi":"Nhà trường đang triển khai một chương trình thử nghiệm dành cho các em nhỏ tập đọc."}]', '[{"phrase":"experimental stage"},{"phrase":"experimental music"},{"phrase":"experimental method"}]', NULL, '/ɪkˌsperɪˈmentl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/exp/exper/experimental__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 13, 'institutional', 'thuộc tổ chức, cơ quan; thuộc thể chế', 'adjective', '[{"en":"Most of the company''s shares are held by institutional investors.","vi":"Phần lớn cổ phần của công ty do các nhà đầu tư tổ chức nắm giữ."},{"en":"The problem is institutional, so one person cannot solve it alone.","vi":"Vấn đề nằm ở cơ chế của cả tổ chức, nên một người không thể tự giải quyết được."},{"en":"Our research project could not continue without institutional support.","vi":"Dự án nghiên cứu của chúng tôi không thể tiếp tục nếu thiếu sự hỗ trợ từ cơ quan."}]', '[{"phrase":"institutional investors"},{"phrase":"institutional support"},{"phrase":"institutional reform"}]', NULL, '/ˌɪnstɪˈtuːʃənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/ins/insti/institutional__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 14, 'slice', 'lát; miếng', 'noun', '[{"en":"Would you like another slice of cake?","vi":"Bạn có muốn ăn thêm một miếng bánh nữa không?"},{"en":"I usually have two slices of toast for breakfast.","vi":"Bữa sáng tôi thường ăn hai lát bánh mì nướng."},{"en":"Put a thin slice of lemon in each glass.","vi":"Cho một lát chanh mỏng vào mỗi cốc."}]', '[{"phrase":"slice of cake"},{"phrase":"slice of bread"},{"phrase":"thin slice"},{"phrase":"slice of pizza"}]', NULL, '/slaɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sli/slice/slice__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 15, 'wander', 'đi lang thang; dạo quanh; lơ đãng', 'verb', '[{"en":"We spent the afternoon wandering around the old town.","vi":"Chúng tôi dành cả buổi chiều dạo quanh khu phố cổ."},{"en":"Don''t let the kids wander off in the crowded market.","vi":"Đừng để bọn trẻ đi lung tung trong khu chợ đông đúc."},{"en":"My mind started to wander during the long meeting.","vi":"Đầu óc tôi bắt đầu lơ đãng trong cuộc họp dài."}]', '[{"phrase":"wander around"},{"phrase":"wander off"},{"phrase":"wander the streets"}]', 'wander (đi lang thang) ≠ wonder (tự hỏi)', '/ˈwɑːndər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wan/wande/wander__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 16, 'empire', 'đế chế; đế quốc', 'noun', '[{"en":"The Roman Empire lasted for hundreds of years.","vi":"Đế chế La Mã tồn tại suốt hàng trăm năm."},{"en":"In history class, we learned about the rise and fall of ancient empires.","vi":"Trong giờ lịch sử, chúng tôi học về sự trỗi dậy và sụp đổ của các đế chế cổ đại."},{"en":"She built a business empire from one small bakery.","vi":"Cô ấy đã gây dựng cả một đế chế kinh doanh từ một tiệm bánh nhỏ."}]', '[{"phrase":"business empire"},{"phrase":"build an empire"},{"phrase":"ancient empire"}]', NULL, '/ˈempaɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/e/emp/empir/empire__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 17, 'subsequently', 'sau đó; về sau', 'adverb', '[{"en":"He started as a waiter and subsequently became the manager of the restaurant.","vi":"Anh ấy khởi đầu là bồi bàn và sau đó trở thành quản lý của nhà hàng."},{"en":"The flight was delayed and subsequently canceled because of fog.","vi":"Chuyến bay bị hoãn rồi sau đó bị hủy vì sương mù."},{"en":"She was injured in the first game and subsequently missed the whole season.","vi":"Cô ấy bị chấn thương ở trận đầu tiên và sau đó phải nghỉ cả mùa giải."}]', '[{"phrase":"subsequently became"},{"phrase":"subsequently published"},{"phrase":"subsequently found"}]', NULL, '/ˈsʌbsɪkwəntli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sub/subse/subsequently__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 18, 'gentle', 'nhẹ nhàng; hiền lành', 'adjective', '[{"en":"Be gentle with the puppy; he''s only a few weeks old.","vi":"Hãy nhẹ tay với chú chó con, nó mới được vài tuần tuổi thôi."},{"en":"My grandmother was a kind and gentle woman.","vi":"Bà tôi là một người phụ nữ tốt bụng và hiền lành."},{"en":"A gentle breeze came in through the open window.","vi":"Một làn gió nhẹ thổi vào qua ô cửa sổ đang mở."}]', '[{"phrase":"gentle breeze"},{"phrase":"be gentle with"},{"phrase":"gentle voice"},{"phrase":"gentle exercise"}]', NULL, '/ˈdʒentl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gentl/gentle__us_3.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 19, 'attendance', 'sự có mặt, sự tham dự; số người tham dự', 'noun', '[{"en":"Good attendance is important if you want to pass this course.","vi":"Đi học đầy đủ rất quan trọng nếu bạn muốn qua môn này."},{"en":"The teacher takes attendance at the start of every class.","vi":"Giáo viên điểm danh vào đầu mỗi buổi học."},{"en":"Attendance at the festival was higher than last year.","vi":"Số người tham dự lễ hội năm nay cao hơn năm ngoái."}]', '[{"phrase":"take attendance"},{"phrase":"attendance at"},{"phrase":"good attendance"},{"phrase":"high attendance"}]', NULL, '/əˈtendəns/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/att/atten/attendance__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 20, 'ownership', 'quyền sở hữu; việc sở hữu', 'noun', '[{"en":"The restaurant has changed ownership three times in five years.","vi":"Nhà hàng này đã đổi chủ ba lần trong năm năm."},{"en":"Home ownership is becoming harder for young people.","vi":"Việc sở hữu nhà ngày càng khó khăn hơn đối với người trẻ."},{"en":"You need these papers to prove ownership of the car.","vi":"Bạn cần những giấy tờ này để chứng minh quyền sở hữu chiếc xe."}]', '[{"phrase":"home ownership"},{"phrase":"change ownership"},{"phrase":"proof of ownership"},{"phrase":"private ownership"}]', NULL, '/ˈəʊnərʃɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/own/owner/ownership__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 21, 'qualification', 'bằng cấp, chứng chỉ; trình độ chuyên môn', 'noun', '[{"en":"She has the right qualifications for the teaching job.","vi":"Cô ấy có bằng cấp phù hợp với công việc giảng dạy."},{"en":"He left school at sixteen without any formal qualifications.","vi":"Anh ấy nghỉ học năm mười sáu tuổi mà không có bằng cấp chính thức nào."},{"en":"What qualifications do you need to become a nurse?","vi":"Bạn cần có bằng cấp gì để trở thành y tá?"}]', '[{"phrase":"formal qualifications"},{"phrase":"professional qualifications"},{"phrase":"academic qualifications"}]', NULL, '/ˌkwɑːlɪfɪˈkeɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/q/qua/quali/qualification__us_4.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 22, 'suspend', 'đình chỉ; tạm ngừng; treo', 'verb', '[{"en":"The student was suspended for three days for fighting.","vi":"Học sinh đó bị đình chỉ học ba ngày vì đánh nhau."},{"en":"Train services were suspended because of the heavy snow.","vi":"Các chuyến tàu bị tạm ngừng vì tuyết rơi dày."},{"en":"A large lamp was suspended from the ceiling above the table.","vi":"Một chiếc đèn lớn được treo từ trần nhà xuống phía trên bàn."}]', '[{"phrase":"temporarily suspend"},{"phrase":"be suspended from school"},{"phrase":"suspend service"}]', NULL, '/səˈspend/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sus/suspe/suspend__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 23, 'functional', 'tiện dụng, thiết thực; hoạt động được', 'adjective', '[{"en":"The kitchen is small but very functional.","vi":"Căn bếp nhỏ nhưng rất tiện dụng."},{"en":"After the storm, the hospital was still fully functional.","vi":"Sau cơn bão, bệnh viện vẫn hoạt động hoàn toàn bình thường."},{"en":"The building''s functional design makes it easy to move around.","vi":"Thiết kế tiện dụng của tòa nhà giúp việc đi lại bên trong rất dễ dàng."}]', '[{"phrase":"fully functional"},{"phrase":"functional design"}]', NULL, '/ˈfʌŋkʃənl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fun/funct/functional__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 24, 'voluntary', 'tự nguyện; tình nguyện', 'adjective', '[{"en":"Taking part in the survey is completely voluntary.","vi":"Việc tham gia khảo sát hoàn toàn là tự nguyện."},{"en":"She does voluntary work at the local hospital on Sundays.","vi":"Cô ấy làm tình nguyện ở bệnh viện địa phương vào các ngày Chủ nhật."},{"en":"The company offered voluntary retirement to its older workers.","vi":"Công ty đưa ra chương trình nghỉ hưu tự nguyện cho những nhân viên lớn tuổi."}]', '[{"phrase":"voluntary work"},{"phrase":"completely voluntary"},{"phrase":"voluntary organization"}]', NULL, '/ˈvɑːlənteri/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/v/vol/volun/voluntary__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 25, 'pale', 'nhợt nhạt, xanh xao; nhạt (màu)', 'adjective', '[{"en":"You look pale; are you feeling all right?","vi":"Trông bạn xanh xao quá, bạn có thấy ổn không?"},{"en":"Her face went pale when she saw the bill.","vi":"Mặt cô ấy tái đi khi nhìn thấy hóa đơn."},{"en":"They painted the bedroom a pale blue color.","vi":"Họ sơn phòng ngủ màu xanh nhạt."}]', '[{"phrase":"look pale"},{"phrase":"turn pale"},{"phrase":"go pale"},{"phrase":"pale blue"}]', NULL, '/peɪl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/p/pal/pale_/pale__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 26, 'stain', 'vết bẩn; vết ố', 'noun', '[{"en":"I can''t get this coffee stain out of my shirt.","vi":"Tôi không tẩy được vết cà phê này trên áo sơ mi."},{"en":"There was a dark stain on the carpet near the sofa.","vi":"Trên thảm gần ghế sofa có một vết bẩn sẫm màu."},{"en":"Wash the tablecloth quickly before the wine stain dries.","vi":"Hãy giặt khăn trải bàn ngay trước khi vết rượu vang khô lại."}]', '[{"phrase":"coffee stain"},{"phrase":"dark stain"},{"phrase":"remove a stain"}]', NULL, '/steɪn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/sta/stain/stain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 27, 'athlete', 'vận động viên', 'noun', '[{"en":"Professional athletes train for several hours every day.","vi":"Các vận động viên chuyên nghiệp tập luyện nhiều giờ mỗi ngày."},{"en":"My brother was a talented athlete in high school.","vi":"Anh trai tôi từng là một vận động viên tài năng hồi cấp ba."},{"en":"Athletes from over fifty countries will compete in the games.","vi":"Vận động viên từ hơn năm mươi quốc gia sẽ tranh tài tại đại hội."}]', '[{"phrase":"professional athlete"},{"phrase":"talented athlete"},{"phrase":"top athlete"}]', NULL, '/ˈæθliːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/ath/athle/athlete__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 28, 'organic', 'hữu cơ', 'adjective', '[{"en":"We buy organic vegetables from a farm near our house.","vi":"Chúng tôi mua rau hữu cơ từ một trang trại gần nhà."},{"en":"Organic food is usually more expensive than regular food.","vi":"Thực phẩm hữu cơ thường đắt hơn thực phẩm thông thường."},{"en":"Fallen leaves are a great source of organic material for your garden.","vi":"Lá rụng là nguồn chất hữu cơ tuyệt vời cho khu vườn của bạn."}]', '[{"phrase":"organic food"},{"phrase":"organic vegetables"},{"phrase":"organic farming"},{"phrase":"organic matter"}]', NULL, '/ɔːrˈɡænɪk/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/o/org/organ/organic__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-09', 29, 'tongue', 'lưỡi; tiếng, ngôn ngữ', 'noun', '[{"en":"Be careful, the soup is hot enough to burn your tongue.","vi":"Cẩn thận nhé, súp nóng đến mức có thể làm bỏng lưỡi đấy."},{"en":"The little boy stuck his tongue out at his sister.","vi":"Cậu bé lè lưỡi trêu chị gái."},{"en":"Although she lives abroad, she still speaks her mother tongue at home.","vi":"Dù sống ở nước ngoài, cô ấy vẫn nói tiếng mẹ đẻ khi ở nhà."}]', '[{"phrase":"mother tongue"},{"phrase":"stick your tongue out"},{"phrase":"bite your tongue"},{"phrase":"burn your tongue"}]', NULL, '/tʌŋ/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ton/tongu/tongue__us_1.mp3', NULL, NULL);
INSERT INTO preset_decks (code, level_code, name, description, color, icon, position) VALUES ('ngsl-6-10', 'ngsl-6', 'Thông dụng 2.501–2.809 · Bộ 10', 'New General Service List, thứ hạng 2.501–2.809', '#3da9fc', 'BookOpen', 10);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 1, 'server', 'máy chủ; người phục vụ', 'noun', '[{"en":"Our web server crashed last night, so nobody could open the site.","vi":"Máy chủ web của chúng tôi bị sập tối qua nên không ai vào được trang web."},{"en":"All our files are stored on a server in another city.","vi":"Tất cả tệp của chúng tôi được lưu trên một máy chủ ở thành phố khác."},{"en":"Our server brought us water before we even ordered.","vi":"Người phục vụ mang nước cho chúng tôi trước cả khi chúng tôi gọi món."}]', '[{"phrase":"web server"},{"phrase":"email server"},{"phrase":"server crash"}]', NULL, '/ˈsɜːrvər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/ser/serve/server__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 2, 'structural', 'thuộc cấu trúc; thuộc kết cấu', 'adjective', '[{"en":"The engineers found serious structural damage after the storm.","vi":"Các kỹ sư phát hiện hư hại nghiêm trọng về kết cấu sau cơn bão."},{"en":"We need to make a few structural changes to the plan.","vi":"Chúng ta cần thực hiện vài thay đổi về cấu trúc trong kế hoạch."},{"en":"Is that wall structural, or can we remove it?","vi":"Bức tường đó có phải tường chịu lực không, hay chúng ta có thể dỡ nó đi?"}]', '[{"phrase":"structural damage"},{"phrase":"structural changes"},{"phrase":"structural problems"}]', NULL, '/ˈstrʌktʃərəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/s/str/struc/structural__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 3, 'website', 'trang web', 'noun', '[{"en":"You can book tickets on our website.","vi":"Bạn có thể đặt vé trên trang web của chúng tôi."},{"en":"She wants to build a website to sell her paintings.","vi":"Cô ấy muốn làm một trang web để bán tranh của mình."},{"en":"Check the school website for the new timetable.","vi":"Hãy xem trang web của trường để biết thời khóa biểu mới."}]', '[{"phrase":"visit a website"},{"phrase":"build a website"},{"phrase":"official website"}]', NULL, '/ˈwebsaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/web/websi/website__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 4, 'fool', 'kẻ ngốc; người khờ dại', 'noun', '[{"en":"I felt like a fool when I realized my mistake.","vi":"Tôi thấy mình như một kẻ ngốc khi nhận ra lỗi của mình."},{"en":"Don''t make a fool of yourself in front of your boss.","vi":"Đừng tự biến mình thành kẻ ngốc trước mặt sếp."},{"en":"Only a fool would drive in this weather.","vi":"Chỉ có kẻ ngốc mới lái xe trong thời tiết thế này."}]', '[{"phrase":"make a fool of yourself"},{"phrase":"feel like a fool"},{"phrase":"such a fool"}]', NULL, '/fuːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/foo/fool_/fool__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 5, 'alongside', 'bên cạnh; cùng với', 'preposition', '[{"en":"A small path runs alongside the river.","vi":"Một con đường nhỏ chạy dọc bên cạnh con sông."},{"en":"I love to work alongside people who enjoy their jobs.","vi":"Tôi thích làm việc cùng những người yêu công việc của họ."},{"en":"Children learn English alongside their other school subjects.","vi":"Trẻ em học tiếng Anh cùng với các môn học khác ở trường."}]', '[{"phrase":"work alongside"},{"phrase":"alongside each other"},{"phrase":"run alongside"}]', NULL, '/əˌlɔːŋˈsaɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/alo/along/alongside__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 6, 'unite', 'đoàn kết; hợp nhất; gắn kết', 'verb', '[{"en":"The big match united the whole town for one evening.","vi":"Trận đấu lớn đã gắn kết cả thị trấn trong một buổi tối."},{"en":"People in the area will unite against the plan to close the park.","vi":"Người dân trong khu vực sẽ đoàn kết chống lại kế hoạch đóng cửa công viên."},{"en":"The two clubs decided to unite and share one stadium.","vi":"Hai câu lạc bộ quyết định hợp nhất và dùng chung một sân vận động."}]', '[{"phrase":"unite against"},{"phrase":"unite behind"},{"phrase":"unite the country"}]', NULL, '/juˈnaɪt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/uni/unite/unite__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 7, 'gently', 'nhẹ nhàng; từ tốn', 'adverb', '[{"en":"She gently closed the door so the baby wouldn''t wake up.","vi":"Cô ấy nhẹ nhàng đóng cửa để em bé không thức giấc."},{"en":"Stir gently and let the soup cook for a few minutes.","vi":"Khuấy nhẹ và để súp nấu thêm vài phút."},{"en":"He smiled and spoke gently to the nervous student.","vi":"Anh ấy mỉm cười và nói chuyện từ tốn với cậu học sinh đang lo lắng."}]', '[{"phrase":"stir gently"},{"phrase":"speak gently"},{"phrase":"smile gently"}]', NULL, '/ˈdʒentli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gen/gentl/gently__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 8, 'compute', 'tính toán; tính ra', 'verb', '[{"en":"The app computes your daily calorie needs automatically.","vi":"Ứng dụng tự động tính lượng calo bạn cần mỗi ngày."},{"en":"The program can compute the average score for each class.","vi":"Chương trình có thể tính điểm trung bình của từng lớp."},{"en":"We computed the total cost of the trip before booking anything.","vi":"Chúng tôi đã tính tổng chi phí chuyến đi trước khi đặt bất cứ thứ gì."}]', '[{"phrase":"compute the average"},{"phrase":"compute the total cost"}]', NULL, '/kəmˈpjuːt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/com/compu/compute__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 9, 'wipe', 'lau; chùi; xóa sạch', 'verb', '[{"en":"Please wipe the table after you finish eating.","vi":"Làm ơn lau bàn sau khi ăn xong."},{"en":"He wiped his hands on a towel.","vi":"Anh ấy lau tay vào khăn."},{"en":"Someone wiped all the files from my old laptop.","vi":"Ai đó đã xóa sạch toàn bộ tệp trong chiếc laptop cũ của tôi."}]', '[{"phrase":"wipe the table"},{"phrase":"wipe your hands"},{"phrase":"wipe clean"}]', NULL, '/waɪp/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wip/wipe_/wipe__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 10, 'weird', 'kỳ lạ; kỳ quặc', 'adjective', '[{"en":"I heard a weird noise coming from the kitchen.","vi":"Tôi nghe thấy một tiếng động lạ phát ra từ nhà bếp."},{"en":"It feels weird to be back at my old school.","vi":"Cảm giác thật lạ khi quay lại ngôi trường cũ."},{"en":"My brother has some weird ideas about food.","vi":"Anh trai tôi có vài ý tưởng kỳ quặc về đồ ăn."}]', '[{"phrase":"weird noise"},{"phrase":"feel weird"},{"phrase":"something weird"}]', NULL, '/wɪrd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/w/wei/weird/weird__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 11, 'gaze', 'nhìn chăm chú; nhìn đăm đăm', 'verb', '[{"en":"She gazed out of the window for a long time.","vi":"Cô ấy nhìn đăm đăm ra ngoài cửa sổ rất lâu."},{"en":"We love to lie on the grass and gaze at the stars.","vi":"Chúng tôi thích nằm trên cỏ và ngắm nhìn các vì sao."},{"en":"He gazed at the painting without saying a word.","vi":"Anh ấy chăm chú nhìn bức tranh mà không nói lời nào."}]', '[{"phrase":"gaze at"},{"phrase":"gaze out of the window"},{"phrase":"gaze into the distance"}]', 'gaze at sb/sth', '/ɡeɪz/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/g/gaz/gaze_/gaze__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 12, 'fade', 'phai màu; mờ dần; nhỏ dần', 'verb', '[{"en":"My favorite jeans faded after a few washes.","vi":"Chiếc quần jean yêu thích của tôi bị phai màu sau vài lần giặt."},{"en":"The music began to fade away as the car drove off.","vi":"Tiếng nhạc bắt đầu nhỏ dần khi chiếc xe chạy đi."},{"en":"Her smile slowly faded when she saw the bill.","vi":"Nụ cười của cô ấy tắt dần khi nhìn thấy hóa đơn."}]', '[{"phrase":"fade away"},{"phrase":"slowly fade"},{"phrase":"memories fade"}]', NULL, '/feɪd/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fad/fade_/fade__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 13, 'cough', 'ho', 'verb', '[{"en":"The smoke made everyone start to cough.","vi":"Khói khiến mọi người bắt đầu ho."},{"en":"My son coughed all night, so neither of us slept.","vi":"Con trai tôi ho cả đêm nên cả hai chúng tôi đều không ngủ được."},{"en":"Cover your mouth when you cough or sneeze.","vi":"Hãy che miệng khi bạn ho hoặc hắt hơi."}]', '[{"phrase":"start to cough"},{"phrase":"cough loudly"},{"phrase":"a bad cough"}]', NULL, '/kɔːf/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cou/cough/cough__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 14, 'hypothesis', 'giả thuyết', 'noun', '[{"en":"These results support the hypothesis that plants grow faster with music.","vi":"Những kết quả này ủng hộ giả thuyết rằng cây mọc nhanh hơn khi có nhạc."},{"en":"Scientists need more data to test this hypothesis.","vi":"Các nhà khoa học cần thêm dữ liệu để kiểm chứng giả thuyết này."},{"en":"Her hypothesis turned out to be completely wrong.","vi":"Giả thuyết của cô ấy hóa ra hoàn toàn sai."}]', '[{"phrase":"support the hypothesis"},{"phrase":"test a hypothesis"},{"phrase":"form a hypothesis"}]', 'số nhiều: hypotheses', '/haɪˈpɑːθəsɪs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/h/hyp/hypot/hypothesis__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 15, 'royal', 'thuộc hoàng gia', 'adjective', '[{"en":"The royal family lived in this palace for centuries.","vi":"Gia đình hoàng gia đã sống trong cung điện này suốt nhiều thế kỷ."},{"en":"We walked around the royal gardens during our trip.","vi":"Chúng tôi đi dạo quanh khu vườn hoàng gia trong chuyến đi."},{"en":"Crowds gathered outside to watch the royal wedding.","vi":"Đám đông tụ tập bên ngoài để xem đám cưới hoàng gia."}]', '[{"phrase":"royal family"},{"phrase":"royal palace"},{"phrase":"royal wedding"}]', NULL, '/ˈrɔɪəl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/roy/royal/royal__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 16, 'theoretical', 'thuộc lý thuyết; trên lý thuyết', 'adjective', '[{"en":"The course gives you theoretical knowledge and practical experience.","vi":"Khóa học mang lại cho bạn kiến thức lý thuyết và kinh nghiệm thực tế."},{"en":"For now, the risk is purely theoretical, so don''t worry.","vi":"Hiện giờ, rủi ro đó chỉ là trên lý thuyết, nên đừng lo."},{"en":"She studies theoretical physics at the university.","vi":"Cô ấy học vật lý lý thuyết ở trường đại học."}]', '[{"phrase":"theoretical knowledge"},{"phrase":"theoretical physics"},{"phrase":"purely theoretical"}]', NULL, '/ˌθiːəˈretɪkl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/the/theor/theoretical__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 17, 'curtain', 'rèm cửa; màn sân khấu', 'noun', '[{"en":"Could you close the curtains because the sun is too bright?","vi":"Bạn kéo rèm lại giúp mình được không, vì nắng chói quá?"},{"en":"She opened the curtains and looked out at the snow.","vi":"Cô ấy kéo rèm ra và nhìn tuyết bên ngoài."},{"en":"The audience clapped loudly when the curtain came down.","vi":"Khán giả vỗ tay rất to khi màn sân khấu hạ xuống."}]', '[{"phrase":"close the curtains"},{"phrase":"open the curtains"},{"phrase":"draw the curtains"},{"phrase":"shower curtain"}]', NULL, '/ˈkɜːrtn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/c/cur/curta/curtain__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 18, 'mayor', 'thị trưởng', 'noun', '[{"en":"The mayor opened the new library this morning.","vi":"Thị trưởng đã khai trương thư viện mới vào sáng nay."},{"en":"The mayor of our town wants to build more bike lanes.","vi":"Thị trưởng thị trấn chúng tôi muốn xây thêm làn đường dành cho xe đạp."},{"en":"Local students wrote a letter to the mayor about the park.","vi":"Học sinh địa phương đã viết thư gửi thị trưởng về công viên."}]', '[{"phrase":"mayor of"},{"phrase":"deputy mayor"},{"phrase":"former mayor"}]', NULL, '/ˈmeɪər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/may/mayor/mayor__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 19, 'darkness', 'bóng tối', 'noun', '[{"en":"The lights went out and the room was in total darkness.","vi":"Đèn tắt và căn phòng chìm trong bóng tối hoàn toàn."},{"en":"My cat''s eyes shine in the darkness.","vi":"Mắt con mèo nhà tôi sáng lên trong bóng tối."},{"en":"We waited in the darkness for the show to begin.","vi":"Chúng tôi chờ trong bóng tối cho đến khi buổi diễn bắt đầu."}]', '[{"phrase":"total darkness"},{"phrase":"in the darkness"},{"phrase":"darkness falls"}]', 'không đếm được', '/ˈdɑːrknəs/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/dar/darkn/darkness__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 20, 'aunt', 'cô; dì; bác gái', 'noun', '[{"en":"My aunt lives in a small village by the sea.","vi":"Dì tôi sống ở một ngôi làng nhỏ ven biển."},{"en":"We''re staying with my aunt and uncle this summer.","vi":"Hè này chúng tôi ở nhà cô chú tôi."},{"en":"Her aunt taught her how to bake bread.","vi":"Dì của cô ấy đã dạy cô ấy cách nướng bánh mì."}]', '[{"phrase":"aunt and uncle"},{"phrase":"favorite aunt"},{"phrase":"great-aunt"}]', NULL, '/ænt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/a/aun/aunt_/aunt__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 21, 'tournament', 'giải đấu', 'noun', '[{"en":"Our school won the basketball tournament last month.","vi":"Trường chúng tôi đã vô địch giải bóng rổ tháng trước."},{"en":"Sixteen teams will take part in the tournament.","vi":"Mười sáu đội sẽ tham gia giải đấu."},{"en":"She hurt her knee before the tennis tournament started.","vi":"Cô ấy bị đau đầu gối trước khi giải quần vợt bắt đầu."}]', '[{"phrase":"win a tournament"},{"phrase":"tennis tournament"},{"phrase":"chess tournament"}]', NULL, '/ˈtʊrnəmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/tou/tourn/tournament__us_1_rr.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 22, 'registration', 'sự đăng ký; việc đăng ký', 'noun', '[{"en":"Registration for the summer course closes on Friday.","vi":"Việc đăng ký khóa học hè sẽ kết thúc vào thứ Sáu."},{"en":"Please bring your ID to the registration desk.","vi":"Vui lòng mang theo giấy tờ tùy thân đến quầy đăng ký."},{"en":"Online registration only takes a few minutes.","vi":"Đăng ký trực tuyến chỉ mất vài phút."}]', '[{"phrase":"registration form"},{"phrase":"registration fee"},{"phrase":"online registration"},{"phrase":"registration desk"}]', NULL, '/ˌredʒɪˈstreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/r/reg/regis/registration__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 23, 'fragment', 'mảnh vỡ; đoạn rời rạc', 'noun', '[{"en":"Small fragments of glass were all over the floor.","vi":"Những mảnh kính vỡ nhỏ vương vãi khắp sàn nhà."},{"en":"I only remember fragments of my dream.","vi":"Tôi chỉ nhớ được vài đoạn rời rạc của giấc mơ."},{"en":"She overheard a fragment of their conversation in the hall.","vi":"Cô ấy nghe lỏm được một đoạn trong cuộc trò chuyện của họ ở hành lang."}]', '[{"phrase":"fragments of glass"},{"phrase":"small fragments"},{"phrase":"a fragment of"}]', NULL, '/ˈfræɡmənt/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/f/fra/fragm/fragment__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 24, 'listener', 'người nghe; thính giả', 'noun', '[{"en":"My grandmother is a very good listener.","vi":"Bà tôi là người rất biết lắng nghe."},{"en":"The radio show has thousands of listeners every morning.","vi":"Chương trình phát thanh có hàng nghìn thính giả mỗi sáng."},{"en":"Good speakers always keep their listeners interested.","vi":"Người nói giỏi luôn khiến người nghe cảm thấy hứng thú."}]', '[{"phrase":"good listener"},{"phrase":"radio listeners"},{"phrase":"regular listener"}]', NULL, '/ˈlɪsənər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/l/lis/liste/listener__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 25, 'immigration', 'sự nhập cư; xuất nhập cảnh', 'noun', '[{"en":"It took us an hour to go through immigration at the airport.","vi":"Chúng tôi mất một tiếng để làm thủ tục nhập cảnh ở sân bay."},{"en":"Please have your passport ready for the immigration officer.","vi":"Vui lòng chuẩn bị sẵn hộ chiếu cho nhân viên xuất nhập cảnh."},{"en":"The city grew quickly because of immigration from nearby countries.","vi":"Thành phố phát triển nhanh nhờ làn sóng nhập cư từ các nước lân cận."}]', '[{"phrase":"go through immigration"},{"phrase":"immigration officer"},{"phrase":"immigration control"}]', 'không đếm được', '/ˌɪmɪˈɡreɪʃn/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/i/imm/immig/immigration__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 26, 'tender', 'mềm; dịu dàng; đau (khi chạm vào)', 'adjective', '[{"en":"Cook the meat slowly until it is tender.","vi":"Nấu thịt thật chậm cho đến khi mềm."},{"en":"She gave the child a tender kiss on the forehead.","vi":"Cô ấy hôn dịu dàng lên trán đứa trẻ."},{"en":"My ankle is still tender after I twisted it.","vi":"Mắt cá chân tôi vẫn còn đau sau khi bị trẹo."}]', '[{"phrase":"tender kiss"},{"phrase":"tender meat"},{"phrase":"tender smile"}]', NULL, '/ˈtendər/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/t/ten/tende/tender__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 27, 'density', 'mật độ; khối lượng riêng', 'noun', '[{"en":"This part of the city has a very high population density.","vi":"Khu vực này của thành phố có mật độ dân số rất cao."},{"en":"Wood floats because it has a lower density than water.","vi":"Gỗ nổi vì có khối lượng riêng nhỏ hơn nước."},{"en":"Low housing density gives this neighborhood a quiet, open feel.","vi":"Mật độ nhà ở thấp mang lại cho khu phố này cảm giác yên tĩnh, thoáng đãng."}]', '[{"phrase":"population density"},{"phrase":"high density"},{"phrase":"low density"},{"phrase":"bone density"}]', NULL, '/ˈdensəti/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/d/den/densi/density__us_1.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 28, 'ugly', 'xấu xí; khó coi; tồi tệ', 'adjective', '[{"en":"Everyone thinks it''s an ugly building, but I like it.","vi":"Ai cũng nghĩ đó là một tòa nhà xấu xí, nhưng tôi lại thích nó."},{"en":"He wore an ugly sweater to the holiday party.","vi":"Anh ấy mặc một chiếc áo len xấu xí đến bữa tiệc ngày lễ."},{"en":"The argument turned ugly, so I left the room.","vi":"Cuộc cãi vã trở nên tồi tệ, nên tôi rời khỏi phòng."}]', '[{"phrase":"ugly building"},{"phrase":"turn ugly"},{"phrase":"ugly scene"}]', NULL, '/ˈʌɡli/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/u/ugl/ugly_/ugly__us_2.mp3', NULL, NULL);
INSERT INTO preset_deck_cards (deck_code, position, english, vietnamese, part_of_speech, examples, collocations, notes, ipa, audio_src, image_url, image_attribution) VALUES ('ngsl-6-10', 29, 'module', 'học phần; mô-đun', 'noun', '[{"en":"Everyone must take the core module in the first term.","vi":"Ai cũng phải học học phần cốt lõi trong học kỳ đầu tiên."},{"en":"I passed all my modules except the one on statistics.","vi":"Tôi đã qua tất cả các học phần, trừ môn thống kê."},{"en":"The software is built from small modules that are easy to update.","vi":"Phần mềm được xây dựng từ các mô-đun nhỏ, dễ cập nhật."}]', '[{"phrase":"core module"},{"phrase":"optional module"},{"phrase":"training module"}]', NULL, '/ˈmɑːdʒuːl/', 'https://www.oxfordlearnersdictionaries.com/media/english/us_pron/m/mod/modul/module__us_1.mp3', NULL, NULL);
